const clozeQuestions = [{"question":"My uncle (　) a small café near the station.","choices":["jumps","runs","swims","flies"],"answer":1,"explanation":"run は「経営する」の意味。"},{"question":"There is (　) time left. We must hurry.","choices":["several","little","many","a few"],"answer":1,"explanation":"time は不可算名詞。little は「ほとんどない」。"},{"question":"I (　) this word in the dictionary.","choices":["came from","looked after","cared for","searched for"],"answer":3,"explanation":"search for は「〜を探す」。"},{"question":"This machine responds (　) to voice commands.","choices":["yesterday","lately","somewhere","automatically"],"answer":3,"explanation":"automatically は「自動的に」。"},{"question":"We should not (　) too much on AI.","choices":["rely","boil","sail","roll"],"answer":0,"explanation":"rely on は「〜に頼る」。"},{"question":"The internet helps us (　) our views.","choices":["dip","boil","broaden","disappear"],"answer":2,"explanation":"broaden は「広げる」。"},{"question":"Can you (　) this sentence into English?","choices":["admire","translate","maintain","control"],"answer":1,"explanation":"translate A into B。"},{"question":"It may (　) a long time to finish the project.","choices":["give","make","take","send"],"answer":2,"explanation":"take time は「時間がかかる」。"},{"question":"She (　) a great idea for the school festival.","choices":["talked to","cared for","came up with","relied on"],"answer":2,"explanation":"come up with は「思いつく」。"},{"question":"I could finish the work (　) your help.","choices":["instead of","because","thanks to","until"],"answer":2,"explanation":"thanks to は「〜のおかげで」。"},{"question":"Please (　) your name to this list.","choices":["add","sail","dip","boil"],"answer":0,"explanation":"add は「加える」。"},{"question":"Keep stirring (　) the sauce becomes thick.","choices":["because of","until","during","from"],"answer":1,"explanation":"until は「〜まで」。"},{"question":"Please (　) the soup with a spoon.","choices":["roll","stir","insert","send"],"answer":1,"explanation":"stir は「かき混ぜる」。"},{"question":"You should (　) the water before adding the pasta.","choices":["cool","roll","boil","dip"],"answer":2,"explanation":"boil は「沸騰させる」。"},{"question":"The plan is (　) enough to continue for many years.","choices":["central","sustainable","distant","physical"],"answer":1,"explanation":"sustainable は「持続可能な」。"},{"question":"The company wants to (　) a new robot.","choices":["develop","remember","admire","disappear"],"answer":0,"explanation":"develop は「開発する」。"},{"question":"This job is difficult but (　).","choices":["rewarding","cheaply","automatically","somewhere"],"answer":0,"explanation":"rewarding は「やりがいのある」。"},{"question":"Many children do not have (　) to clean water.","choices":["cotton","career","access","sail"],"answer":2,"explanation":"have access to は「〜を利用できる」。"},{"question":"The graph shows the (　) of students who walk to school.","choices":["microphone","pirate","percentage","cape"],"answer":2,"explanation":"percentage は「割合」。"},{"question":"She works hard to (　) her dream come true.","choices":["have","make","take","send"],"answer":1,"explanation":"make + 目的語 + 原形。"},{"question":"This book made me (　) in science.","choices":["interested","interests","interesting","interest"],"answer":0,"explanation":"make A interested in B。"},{"question":"My brother is (　) to become a doctor.","choices":["hopes","hope","hoped","hoping"],"answer":3,"explanation":"be hoping to + 動詞の原形。"},{"question":"My dream finally came (　).","choices":["truly","truth","true","truer"],"answer":2,"explanation":"come true は「実現する」。"},{"question":"We should (　) old paper instead of throwing it away.","choices":["represent","recognize","recycle","respond"],"answer":2,"explanation":"recycle は「再利用する」。"},{"question":"I (　) an old friend on my way home.","choices":["came up","came across","came true","came from"],"answer":1,"explanation":"come across は「偶然出会う」。"},{"question":"My sister (　) our dog when we are away.","choices":["cares for","comes across","takes off","gives up"],"answer":0,"explanation":"care for は「世話をする」。"},{"question":"The news (　) many people around the world.","choices":["inserted","admired","stirred","affected"],"answer":3,"explanation":"affect は「影響を与える」。"},{"question":"The scientist (　) the results to the students.","choices":["dipped","rolled","explained","disappeared"],"answer":2,"explanation":"explain は「説明する」。"},{"question":"I want to (　) enough money to buy a new bicycle.","choices":["stir","sail","earn","dip"],"answer":2,"explanation":"earn は「稼ぐ」。"},{"question":"The robot can (　) human faces.","choices":["recognize","recycle","earn","boil"],"answer":0,"explanation":"recognize は「認識する」。"},{"question":"The new machine has an important (　).","choices":["function","marriage","poverty","adventure"],"answer":0,"explanation":"function は「機能」。"},{"question":"This experience was a real (　) for me.","choices":["eye-opener","microphone","baking sheet","search engine"],"answer":0,"explanation":"eye-opener は「新たな気づきを与える経験」。"},{"question":"The price is low because the bags are made (　).","choices":["large","thick","real","cheaply"],"answer":3,"explanation":"cheaply は「安く」。"},{"question":"My father (　) me to clean my room.","choices":["let to","had to","made","got"],"answer":2,"explanation":"make + 人 + 原形。"},{"question":"The city is famous (　) its beautiful park.","choices":["from","for","to","at"],"answer":1,"explanation":"be famous for。"},{"question":"This information is useful (　) everyone.","choices":["by","from","for","of"],"answer":2,"explanation":"useful for。"},{"question":"We must (　) the environment for the future.","choices":["insert","protect","translate","roll"],"answer":1,"explanation":"環境を守るという文脈。"},{"question":"I (　) impressed by her presentation.","choices":["was","am","were","be"],"answer":0,"explanation":"過去の感想を表す。"},{"question":"There are (　) and more people using AI.","choices":["much","many","most","more"],"answer":3,"explanation":"more and more。"},{"question":"I think that not (　) robots are useful.","choices":["any","each","every","all"],"answer":3,"explanation":"not all は部分否定。"},{"question":"The boy (　) lives next door is my friend.","choices":["where","when","who","what"],"answer":2,"explanation":"人を先行詞とする主格。"},{"question":"The bike (　) I bought yesterday is blue.","choices":["which","what","who","where"],"answer":0,"explanation":"物を先行詞とする目的格。省略も可能。"},{"question":"The boy (　) is running in the park is my cousin.","choices":["where","which","who","what"],"answer":2,"explanation":"先行詞は人。空欄の後に動詞が続くので主格の who。"},{"question":"The dog (　) is sleeping under the table is mine.","choices":["which","what","where","who"],"answer":0,"explanation":"物・動物を先行詞とする主格。"},{"question":"The singer (　) we met yesterday was kind.","choices":["what","who","where","which"],"answer":1,"explanation":"人を先行詞とする目的格。省略も可能。"},{"question":"The book (　) is on the desk belongs to me.","choices":["where","that","what","when"],"answer":1,"explanation":"物を先行詞とする主格。"},{"question":"The book (　) I read last week was interesting.","choices":["where","which","who","what"],"answer":1,"explanation":"先行詞は物。I read の目的語が欠けているので目的格の which。"},{"question":"The man (　) teaches English is from Canada.","choices":["what","when","where","who"],"answer":3,"explanation":"主格。"},{"question":"The picture (　) she drew is beautiful.","choices":["who","where","what","that"],"answer":3,"explanation":"目的格。省略も可能。"},{"question":"The people (　) work here are very friendly.","choices":["where","what","when","who"],"answer":3,"explanation":"主格。"},{"question":"The movie (　) we watched last night was exciting.","choices":["what","who","which","where"],"answer":2,"explanation":"目的格。省略も可能。"},{"question":"The student (　) helped me was very kind.","choices":["what","that","where","when"],"answer":1,"explanation":"主格。"},{"question":"The robot (　) can speak three languages is new.","choices":["who","which","what","where"],"answer":1,"explanation":"主格。"},{"question":"The teacher (　) I talked to yesterday is nice.","choices":["what","which","where","who"],"answer":3,"explanation":"目的格。省略も可能。"},{"question":"The girl (　) plays the piano is my friend.","choices":["where","who","which","what"],"answer":1,"explanation":"先行詞は人。空欄の後に動詞が続くので主格の who。"},{"question":"The cake (　) my mother made was delicious.","choices":["who","what","that","where"],"answer":2,"explanation":"目的格。省略も可能。"},{"question":"The player (　) scored the goal is my cousin.","choices":["what","where","when","who"],"answer":3,"explanation":"主格。"},{"question":"The song (　) I heard on the radio is popular.","choices":["where","which","what","who"],"answer":1,"explanation":"目的格。省略も可能。"},{"question":"The cat (　) is sleeping on the sofa is mine.","choices":["which","who","where","what"],"answer":0,"explanation":"先行詞は動物。主格の which。"},{"question":"The computer (　) my brother uses is very old.","choices":["that","what","where","who"],"answer":0,"explanation":"目的格。省略も可能。"},{"question":"The girl (　) by the window is my sister.","choices":["stood","stands","standing","stand"],"answer":2,"explanation":"現在分詞による後置修飾。"},{"question":"The cake (　) by my mother was delicious.","choices":["made","making","make","makes"],"answer":0,"explanation":"過去分詞による後置修飾。"},{"question":"Do you know the boy (　) soccer over there?","choices":["play","played","plays","playing"],"answer":3,"explanation":"現在分詞による後置修飾。"},{"question":"The letter (　) in English is from my friend.","choices":["wrote","writes","written","writing"],"answer":2,"explanation":"過去分詞による後置修飾。"},{"question":"The woman (　) to the teacher is my aunt.","choices":["talks","talked","talk","talking"],"answer":3,"explanation":"現在分詞。"},{"question":"The picture (　) by the artist is famous.","choices":["paint","paints","painted","painting"],"answer":2,"explanation":"過去分詞。"},{"question":"The students (　) in the library are in my class.","choices":["studied","study","studying","studies"],"answer":2,"explanation":"現在分詞。"},{"question":"The bridge (　) in 1990 is still used.","choices":["built","building","builds","build"],"answer":0,"explanation":"過去分詞。"},{"question":"The dog (　) in the garden is very cute.","choices":["ran","running","runs","run"],"answer":1,"explanation":"現在分詞。"},{"question":"The song (　) by her is popular.","choices":["sung","sang","singing","sings"],"answer":0,"explanation":"過去分詞。"},{"question":"Do you know (　) she lives?","choices":["what","where","who","which"],"answer":1,"explanation":"間接疑問文。"},{"question":"Please tell me (　) you made this cake.","choices":["how","who","what","which"],"answer":0,"explanation":"作り方を聞く。"},{"question":"I do not know (　) he is late.","choices":["who","what","why","which"],"answer":2,"explanation":"理由を聞く。"},{"question":"Can you tell me (　) the library opens?","choices":["who","what","when","which"],"answer":2,"explanation":"時刻を聞く。"},{"question":"Do you know (　) this word means?","choices":["what","when","where","who"],"answer":0,"explanation":"意味を聞く。"},{"question":"I wonder (　) she will come tomorrow.","choices":["who","if","what","which"],"answer":1,"explanation":"〜かどうか。"},{"question":"Please tell me (　) to get to the station.","choices":["how","who","what","which"],"answer":0,"explanation":"how to + 動詞。"},{"question":"I do not know (　) to choose.","choices":["where","which","who","what"],"answer":1,"explanation":"どちらを選ぶか。"},{"question":"The movie (　) we watched yesterday was exciting.","choices":["who","where","that","what"],"answer":2,"explanation":"先行詞は物。目的格の that。省略も可能。"},{"question":"I want to know (　) he said.","choices":["where","what","when","who"],"answer":1,"explanation":"何を言ったか。"},{"question":"The company (　) products to many countries.","choices":["stirs","sends","dips","rolls"],"answer":1,"explanation":"send は「送る」。"},{"question":"This device is very (　) when I travel.","choices":["handy","imperfect","physical","distant"],"answer":0,"explanation":"handy は「便利な」。"},{"question":"I want to learn more about different (　).","choices":["viewpoints","microphones","stems","syrups"],"answer":0,"explanation":"viewpoint は「観点」。"},{"question":"We need to (　) this problem together.","choices":["roll","solve","boil","sail"],"answer":1,"explanation":"solve は「解決する」。"},{"question":"I hope to (　) my English skills.","choices":["boil","dip","improve","sail"],"answer":2,"explanation":"能力を高める。"},{"question":"She gave an excellent (　) in class.","choices":["poverty","electricity","presentation","housework"],"answer":2,"explanation":"presentation は「発表」。"},{"question":"Many people suffer from (　) in that region.","choices":["poverty","syrup","recipe","cotton"],"answer":0,"explanation":"poverty は「貧困」。"},{"question":"The (　) shows how electricity use has changed.","choices":["stem","cape","graph","pirate"],"answer":2,"explanation":"graph は「グラフ」。"},{"question":"My sister wants a (　) in medicine.","choices":["syrup","command","cape","career"],"answer":3,"explanation":"career は「職業・経歴」。"},{"question":"The robot can (　) the temperature.","choices":["sail","control","boil","admire"],"answer":1,"explanation":"control は「制御する」。"},{"question":"We should (　) good relationships with others.","choices":["disappear","maintain","dip","roll"],"answer":1,"explanation":"maintain は「維持する」。"},{"question":"The accident caused a serious (　).","choices":["device","recipe","cape","injury"],"answer":3,"explanation":"injury は「けが」。"},{"question":"The (　) of this product is increasing.","choices":["illness","adventure","production","marriage"],"answer":2,"explanation":"production は「生産」。"},{"question":"She works for a large (　) in Tokyo.","choices":["stem","syrup","cape","company"],"answer":3,"explanation":"company は「会社」。"},{"question":"I want to (　) people who work for peace.","choices":["boil","admire","stir","dip"],"answer":1,"explanation":"admire は「尊敬する」。"},{"question":"I could (　) the problem with my friend.","choices":["boil","sail","roll","discuss"],"answer":3,"explanation":"議論する。"},{"question":"We can learn about the world (　) the internet.","choices":["through","around","until","under"],"answer":0,"explanation":"インターネットを通じて。"},{"question":"The robot is (　) by a computer.","choices":["controlling","controls","control","controlled"],"answer":3,"explanation":"受動態。"},{"question":"I was (　) by the story.","choices":["impressed","impressing","impresses","impress"],"answer":0,"explanation":"be impressed by。"},{"question":"This is one of the most (　) days of my life.","choices":["memorable","cheaply","somewhere","automatically"],"answer":0,"explanation":"memorable は「忘れられない」。"},{"question":"Our school has students from (　) countries.","choices":["imperfect","distant","physical","thick"],"answer":1,"explanation":"distant は「遠い」。"},{"question":"She is interested (　) fair trade.","choices":["at","of","in","from"],"answer":2,"explanation":"be interested in。"},{"question":"He showed me (　) to use the app.","choices":["which","who","how","what"],"answer":2,"explanation":"how to + 動詞。"},{"question":"We need enough food (　) feed everyone.","choices":["for","with","by","to"],"answer":3,"explanation":"enough + 名詞 + to。"},{"question":"The boy is (　) for his lost dog.","choices":["searching","search","searched","searches"],"answer":0,"explanation":"現在進行形。"}];

const collections={civics:{title:'中学3年 公民',questions:civicsQuestions},history:{title:'中学2年 歴史',questions:historyQuestions},vocab:{title:'英語｜単語・熟語',questions:vocabQuestions},cloze:{title:'英語｜英文穴埋め',questions:clozeQuestions}};
const $=id=>document.getElementById(id);let currentCollection=collections.civics;let active=[],index=0,answers=[];
function show(page){for(const id of ['home','english-menu','intro','quiz','result'])$(id).classList.toggle('hidden',id!==page);window.scrollTo({top:0,behavior:'instant'});}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
function selectCollection(key){currentCollection=collections[key];$('intro-title').textContent=currentCollection.title;$('intro-info').textContent=`全${currentCollection.questions.length}問からランダムで10問出題します。間違えた問題だけの復習もできます。`;show('intro');}
function begin(items,isReview=false){active=items.map(q=>({...q,choices:[...q.choices]}));index=0;answers=[];$('mode').textContent=isReview?'間違えた問題の復習':currentCollection.title;show('quiz');render();}
function newRound(){begin(shuffle(currentCollection.questions).slice(0,10));}
function render(){const q=active[index];$('progress').textContent=`${index+1} / ${active.length}問`;$('progress-bar').style.width=`${(index+1)/active.length*100}%`;$('question').textContent=q.question;$('feedback').textContent='';$('feedback').className='feedback';$('explanation').textContent='';$('explanation').classList.add('hidden');$('next').classList.add('hidden');$('next').textContent=index===active.length-1?'結果を見る →':'次の問題へ →';$('choices').replaceChildren();q.choices.forEach((choice,i)=>{const b=document.createElement('button');b.className='choice';b.textContent=`${'ABCD'[i]}. ${choice}`;b.onclick=()=>answer(i);$('choices').append(b);});}
function answer(chosen){if(answers.length!==index)return;const q=active[index],correct=chosen===q.answer;answers.push({question:q,correct});[...$('choices').children].forEach((b,i)=>{b.disabled=true;if(i===q.answer)b.classList.add('correct');if(i===chosen&&!correct)b.classList.add('wrong');});$('feedback').className=`feedback ${correct?'good':'bad'}`;$('feedback').textContent=correct?'○ 正解！':`× 不正解　正解：${q.choices[q.answer]}`;if(q.explanation){$('explanation').textContent=q.explanation;$('explanation').classList.remove('hidden');}$('next').classList.remove('hidden');}
function results(){show('result');const count=answers.filter(a=>a.correct).length;const missed=answers.filter(a=>!a.correct).map(a=>a.question);$('score').textContent=`${count} / ${answers.length}問 正解`;$('summary').textContent=`正答率 ${Math.round(count/answers.length*100)}%`;$('history').replaceChildren();answers.forEach((a,i)=>{const s=document.createElement('span');s.className=a.correct?'ok':'ng';s.textContent=`${i+1}問 ${a.correct?'○':'×'}`;$('history').append(s);});$('retry').classList.toggle('hidden',missed.length===0);$('retry').textContent=`間違えた${missed.length}問を復習する`;$('retry').onclick=()=>begin(missed,true);}
document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{if(b.dataset.subject==='english')show('english-menu');else selectCollection(b.dataset.subject);});$('vocab-count').textContent=`全${vocabQuestions.length}問`;$('cloze-count').textContent=`全${clozeQuestions.length}問`;$('english-back').onclick=()=>show('home');$('intro-back').onclick=()=>show(currentCollection===collections.civics?'home':'english-menu');$('start').onclick=newRound;$('again').onclick=newRound;$('back').onclick=()=>show('home');$('next').onclick=()=>{if(index+1===active.length)results();else{index++;render();}};
